import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Media Package, Campaign and Chat — scoped UI refresh","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/ui-refresh/spec.md","filePath":"feature/media-package-campaign/ui-refresh/spec.md"}'),s={name:"feature/media-package-campaign/ui-refresh/spec.md"};function r(o,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="media-package-campaign-and-chat-—-scoped-ui-refresh" tabindex="-1">Media Package, Campaign and Chat — scoped UI refresh <a class="header-anchor" href="#media-package-campaign-and-chat-—-scoped-ui-refresh" aria-label="Permalink to &quot;Media Package, Campaign and Chat — scoped UI refresh&quot;">​</a></h1><h2 id="current-amendment-—-2026-10-19" tabindex="-1">Current amendment — 2026-10-19 <a class="header-anchor" href="#current-amendment-—-2026-10-19" aria-label="Permalink to &quot;Current amendment — 2026-10-19&quot;">​</a></h2><p>User requests compact Package/Campaign headers, grouped readable Package terms/deliverables with clear value labels, secondary explanations behind keyboard/touch-accessible question-mark help, and a top Change package action exposing the catalogue without scrolling. Preserve selection/approved/Campaign locks and negotiation dirty guards; no new role permissions. Remove redundant Campaign partner link (already in menu), duplicate heading/description and Task Detail approval shortcut. Fix approval page height propagation/independent scrolling with long media without changing shared PageWrapper for other pages.</p><p>Campaign end date: user confirmed auto-filled suggestion, still editable by Manager; source is approved agreement durationWeeks, never mutable catalogue. Suggest start + weeks*7 calendar days (not minus one); missing duration keeps manual input. Preserve manually chosen end dates when start changes, unless end is empty or matches the previous calculated suggestion. Reopening existing drafts must not rewrite stored dates. No backend/schema/data edits.</p><h2 id="objective-user-story" tabindex="-1">Objective / user story <a class="header-anchor" href="#objective-user-story" aria-label="Permalink to &quot;Objective / user story&quot;">​</a></h2><p>Owner manages Agency packages; Client and Manager review package terms and the single Campaign in a Workspace; active members exchange plain-text chat messages. Improve readability and navigation without changing the existing business contracts. User approved the layout and added Chat to scope on 2026-10-10.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Package catalogue puts name, value and deliverables before secondary actions; local search/filter does not change API results or availability permissions.</li><li>Detail view groups scope, deliverables and acceptance criteria. Negotiation keeps the current version, Client proposal count and both approvals visible. Compare previous/current terms with textual change indicators, not colour alone.</li><li>Package approval leads to the existing Campaign route, not an embedded second Campaign editor. Keep one Campaign/Workspace, immutable approved content, total quantities, Client feedback/Manager editing and version-bound approvals unchanged.</li><li>Campaign groups plan, review and deployment/progress; differences show business labels and structured milestones/work items rather than raw JSON.</li><li>Chat retains existing history, context, connection and delivery states; readable messages, day separators and composer. No attachments/reactions/read receipts.</li><li>Closing an edited package form requires confirmation; pending requests cannot dismiss the form. No persistent draft storage or backend changes.</li><li>All new labels use parallel <code>mediaPackage.ui.*</code>, <code>campaign.ui.*</code>, <code>chat.ui.*</code> keys in vi/en. Existing font, semantic colour tokens and light/dark modes are retained.</li><li>Responsive at 375/768/1440px; visible keyboard focus, labelled inputs and no unintended horizontal page overflow. Loading/error/empty states remain usable.</li><li>No changes to global CSS/theme, shared primitives/layout/sidebar/routes/access, other pages, service payloads, database or existing uncommitted partner work.</li></ul><h2 id="api-errors-edge-cases" tabindex="-1">API / errors / edge cases <a class="header-anchor" href="#api-errors-edge-cases" aria-label="Permalink to &quot;API / errors / edge cases&quot;">​</a></h2><p>Reuse existing services and hooks. Keep role checks, package gate, conflicts, proposal limits, deployment retry and completion reasons. No automatic approval, deploy, Task completion or data mutation during browser verification.</p><h2 id="sources-out-of-scope-dod" tabindex="-1">Sources / out of scope / DoD <a class="header-anchor" href="#sources-out-of-scope-dod" aria-label="Permalink to &quot;Sources / out of scope / DoD&quot;">​</a></h2><p>Sources: ../phase-1-design/spec.md, ../README.md, ../../../ba/04-media-package-campaign.md, ../../content-task-workflow/3-6-36-realtime-workspace-chat/spec.md and brandhub-web/rule.md. Out of scope: reports, new Jira tasks, backend/data changes and UI owned by others. DoD: scoped diff, type-check/lint/build, existing regression suite and browser evidence where available. Environment limitations are recorded, not marked passed.</p><h2 id="ui-corrections-—-2026-10-11" tabindex="-1">UI corrections — 2026-10-11 <a class="header-anchor" href="#ui-corrections-—-2026-10-11" aria-label="Permalink to &quot;UI corrections — 2026-10-11&quot;">​</a></h2><ul><li>Campaign form separates milestones and planned work items into named sections. Use distinct <code>campaign.milestoneName</code> / <code>campaign.workItemName</code> labels in vi/en; milestone guidance explains dates only, work-item guidance explains Task creation after deployment. No shared “work item / milestone” label or payload changes.</li><li>Catalogue search, availability filter and result count must remain separate, operable controls, including the Owner catalogue where the filter is present.</li><li>Vietnamese Package/Campaign approval labels use “khách hàng” and “công ty truyền thông/quản lý”; remove parenthesized English role/approval labels. English locale remains available, with parallel keys unchanged.</li><li>Campaign permissions resolve from the Workspace in the URL, matching the shared access guard, not a stale selected Workspace role. Managers can edit valid DRAFT plans. APPROVED/IN_PROGRESS/COMPLETED plans remain immutable; show why editing is unavailable instead of silently hiding the action. Legacy guards remain intact.</li><li>No backend or shared primitive/access changes; no reopening an approved Campaign.</li></ul><p>User-approved data correction: restore only draft Campaign <code>d366c84e-93c3-41c8-b433-5bab58a14341</code> in Workspace <code>b84bd2d0-b069-44e9-95e1-1f7b5bc8111d</code>. Its frozen v3 package snapshot equals the approved Workspace terms and contains 2 deliverables, but deliverable_plan is empty. Copy those snapshot deliverables only; keep status/contentVersion/approvals/work items unchanged. This is not a schema migration or a conversion of monthly quantities.</p>',15)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
